entries[106728] = { ["name"] = "Tetanus", ["text"] = "Unbegrenzte Reichweite\nSofort\nDie Angriffe des Elementiumschrecken rufen Tetanus hervor. Der Effekt verursacht 70200 bis 73800 körperlichen Schaden und zusätzlich alle 1 Sek. 26325 bis 27675 körperlichen Schaden. Stapelbar.\n(1s Abklingzeit)" }
